#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ReaderPosition {
    /// Document epoch; replacement invalidates the position.
    pub epoch: u64,
    /// View that produced the position.
    pub view: ViewType,
    /// Exact or nearest source byte location.
    pub source_byte: usize,
    /// Precise rendered location, when captured from that representation.
    pub reading: Option<ReadingPosition>,
    /// Desired viewport row of the location.
    pub viewport_row: u32,
    /// Horizontal viewport offset for an unwrapped view.
    pub horizontal: u32,
}

/// The document representation displayed by the reader.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum ViewType {
    /// Reading presentation with actionable cards and links.
    #[default]
    Rendered,
    /// Original Markdown text with exact source copying.
    Source,
}

impl CommandType for ViewType {}

impl FromArgValue for ViewType {}

impl ToArgValue for ViewType {}

pub mod document {
    //! Semantic documents, source mappings, and actionable objects.
    //! Source-addressed Markdown semantics, independent of widgets and geometry.

    pub use pulldown_cmark::Alignment;
    /// An alert quote a block lies in.
    #[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
    pub struct Alert {
        /// The alert's tone.
        pub tone: AlertTone,
        /// The alert quote's rail, counting quote rails from the outermost.
        pub depth: usize,
    }

    /// The semantic tone of an alert, which sets its colour.
    ///
    /// GitHub defines five alert kinds, and other tools, such as Obsidian,
    /// MkDocs, Docusaurus, and reStructuredText, use overlapping vocabularies.
    /// Each common label takes the tone of the GitHub kind closest in meaning.
    #[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
    pub enum AlertTone {
        /// Information worth noticing: note, info, todo, abstract, summary,
        /// tldr, quote, cite, and example.
        Note,
        /// Advice or success: tip, hint, success, check, and done.
        Tip,
        /// Information needed to succeed: important.
        Important,
        /// Something that needs attention: warning, attention, question, help,
        /// and faq.
        Warning,
        /// Risk or failure: caution, danger, error, failure, fail, missing, and
        /// bug.
        Caution,
    }

    impl AlertTone {
        /// Return the tone of an alert label, ignoring case, or nothing for a
        /// label no common vocabulary uses.
        #[must_use]
        pub fn of(label: &str) -> Option<Self>;
    }

    /// One semantic leaf with source and container metadata.
    #[derive(Clone, Debug)]
    pub struct Block {
        /// Opaque identity that is never recycled within its source epoch.
        pub id: u64,
        /// Original UTF-8 source range for this construct.
        pub source: Range<usize>,
        /// Semantic construct or payload category.
        pub kind: BlockKind,
        /// Identity of the associated reading unit.
        pub unit_id: u64,
        /// List and quote container nesting depth.
        pub depth: usize,
        /// Number of enclosing quote rails.
        pub quote_depth: usize,
        /// Uppercase alert label on the first leaf of an alert quote.
        pub quote_kind: Option<String>,
        /// Quote rails that continue past this block into the next, because
        /// both lie in the same quotes.
        pub quote_join: usize,
        /// The alert quotes this block lies in, outermost first.
        pub alerts: Vec<Alert>,
        /// A generated bullet or parser-derived ordered marker.
        pub list_marker: Option<String>,
        /// Whether this leaf remains open at the receiving boundary.
        pub provisional: bool,
    }

    /// An Obsidian block id, `^id`, and the block it marks.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub struct BlockAnchor {
        /// The id, without its `^`.
        pub id: String,
        /// The source of the marked block.
        pub source: Range<usize>,
    }

    /// The interpreted construct associated with one reading unit.
    #[derive(Clone, Debug)]
    pub enum BlockKind {
        /// An ordinary paragraph or tight-list text leaf.
        Paragraph,
        /// A heading indexed by the outline and fragment resolver.
        Heading {
            /// Heading level from one through six.
            level: u8,
        },
        /// Parser-normalized code, selectable as one card.
        Code(CodeBlock),
        /// A completed table with normalized cell values.
        Table(MarkdownTable),
        /// Exact source retained for inspection or literal presentation.
        Source {
            /// Why the block shows as source rather than rendered, or empty for
            /// source that always shows as itself, such as HTML.
            reason: String,
        },
        /// A thematic rule without readable decoration.
        Rule,
        /// A labeled footnote block or reference.
        Footnote {
            /// The readable label or footnote identifier.
            label: String,
        },
        /// An image alone in its paragraph, which a host may supply.
        Image(ImageBlock),
    }

    /// Parser-normalized code payload and its original fence information.
    #[derive(Clone, Debug)]
    pub struct CodeBlock {
        /// The complete parser-decoded fence info string.
        pub info: String,
        /// Normalized code bytes, preserving content whitespace and final LF.
        pub payload: Arc<str>,
        /// Whether the trailing code block is still receiving content.
        pub receiving: bool,
    }

    /// Immutable semantic interpretation of one accepted source revision.
    #[derive(Clone, Debug)]
    pub struct DocumentSnapshot {
        /// Accepted bytes and lifecycle interpreted by this snapshot.
        pub source: SourceSnapshot,
        /// Construction bounds used for this snapshot.
        pub limits: ParseLimits,
        /// Semantic leaves in source order.
        pub blocks: Vec<Block>,
        /// Readable payloads in the same order as blocks.
        pub units: Vec<ReadingUnit>,
        /// Explicit targets admitted outside the provisional region.
        pub objects: Vec<Object>,
        /// Heading index in source order.
        pub outline: Vec<OutlineEntry>,
        /// Obsidian block ids in source order, each naming the block it marks.
        /// The first block with an id keeps it.
        pub block_anchors: Vec<BlockAnchor>,
        /// The trailing source region awaiting a closing boundary.
        pub provisional: Option<Range<usize>>,
        /// Whether a derived-work bound required a source-card fallback.
        pub degraded: bool,
        /* private fields */
    }

    impl DocumentSnapshot {
        /// Materialize a displayed selection, expanding atomic cards.
        pub fn copy_range(&self, range: &ReadingRange) -> Option<String>;

        /// Conservative owned semantic-model bytes, excluding accepted source and
        /// flattened parser input. This worker-computed observation is constant
        /// time.
        pub fn derived_bytes(&self) -> usize;

        /// Materialize the complete rendered copy projection.
        pub fn readable_text(&self) -> String;

        /// Restore by identity, then containing source span, then the nearest
        /// source neighbor.
        pub fn resolve_anchor(
            &self,
            id: u64,
            source_start: usize,
            offset: usize,
        ) -> Option<ReadingPosition>;

        /// Look up one reading unit by its opaque identity.
        pub fn unit(&self, id: u64) -> Option<&ReadingUnit>;
    }

    /// An image alone in its paragraph: `![alt](path)`, or Obsidian's
    /// `![[path]]` with an optional `|width` or `|widthxheight` size in pixels.
    #[derive(Clone, Debug, Eq, Hash, PartialEq)]
    pub struct ImageBlock {
        /// The image's destination, and its alt text as the label.
        pub link: Link,
        /// The width the source asks for, in pixels.
        pub width: Option<u32>,
        /// The height the source asks for, in pixels.
        pub height: Option<u32>,
    }

    /// Semantic emphasis independent of terminal geometry and palette.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum InlineRole {
        /// Emphasized inline text.
        Emphasis,
        /// Strong inline emphasis.
        Strong,
        /// Parser-normalized code, selectable as one card.
        Code,
        /// Struck-through inline text.
        Strike,
        /// A parser link or recognized bare HTTP(S) URL.
        Link,
    }

    /// A UTF-8 byte range in a reading unit and its semantic role.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub struct InlineSpan {
        /// UTF-8 byte range in the addressed readable text.
        pub range: Range<usize>,
        /// Semantic text role used during presentation.
        pub role: InlineRole,
        /// Associated actionable object, when admitted.
        pub object: Option<u64>,
    }

    /// A readable label and its original destination and title.
    #[derive(Clone, Debug, Eq, Hash, PartialEq)]
    pub struct Link {
        /// The readable label or footnote identifier.
        pub label: String,
        /// The original parser-decoded URL destination.
        pub destination: String,
        /// The optional parser-decoded link title.
        pub title: String,
        /// Whether the source wrote a `[[target|label]]` wikilink, whose
        /// destination names a host document rather than a URL.
        pub wiki: bool,
        /// Whether the source gave the label: always for a Markdown link, and
        /// for a wikilink only after a `|`. An unlabelled wikilink shows its
        /// target as Obsidian does, `Note › Heading`.
        pub labelled: bool,
    }

    impl Link {
        /// Classify the destination. A wikilink is always local to the host;
        /// other destinations resolve as [`resolve_link`] does.
        pub fn resolve(&self, base: Option<&Url>) -> ResolvedLink;
    }

    /// A link to a document of the host's own: a relative or absolute path, a
    /// `file:` URL, or a wikilink. The reader never touches the filesystem; the
    /// host decides what the path names.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub struct LocalLink {
        /// The percent-decoded path, as written, without its fragment.
        pub path: String,
        /// The percent-decoded heading or block anchor after `#`, if any.
        pub fragment: Option<String>,
        /// Whether a wikilink named the document. Its path may omit an
        /// extension, and the host may resolve it by name.
        pub wiki: bool,
    }

    /// Parser-normalized table data without terminal geometry.
    #[derive(Clone, Debug)]
    pub struct MarkdownTable {
        /// Parser column alignments in header order.
        pub alignments: Vec<Alignment>,
        /// Whether source rows contain excess cells omitted by the parser.
        pub ignored_excess: bool,
        /// Ordered header cells that define column keys.
        pub headers: Vec<TableCell>,
        /// Ordered body rows, excluding the header.
        pub rows: Vec<TableRow>,
    }

    /// One source-addressed interaction target within a document epoch.
    #[derive(Clone, Debug)]
    pub struct Object {
        /// Opaque identity that is never recycled within its source epoch.
        pub id: u64,
        /// Original UTF-8 source range for this construct.
        pub source: Range<usize>,
        /// Identity of the associated reading unit.
        pub unit_id: u64,
        /// Semantic construct or payload category.
        pub kind: ObjectKind,
    }

    /// An explicit interaction target outside provisional content.
    #[derive(Clone, Debug)]
    pub enum ObjectKind {
        /// A parser link or recognized bare HTTP(S) URL.
        Link(Link),
        /// Parser-normalized code, selectable as one card.
        Code,
        /// A completed table with normalized cell values.
        Table,
        /// Exact source retained for inspection or literal presentation.
        Source,
        /// A labeled footnote block or reference.
        Footnote {
            /// The readable label or footnote identifier.
            label: String,
        },
    }

    /// One heading, its source identity, and its disambiguated fragment.
    #[derive(Clone, Debug)]
    pub struct OutlineEntry {
        /// Opaque identity that is never recycled within its source epoch.
        pub id: u64,
        /// Identity of the associated reading unit.
        pub unit_id: u64,
        /// Original UTF-8 source range for this construct.
        pub source: Range<usize>,
        /// Heading level from one through six.
        pub level: u8,
        /// Readable text, excluding generated terminal decoration.
        pub text: String,
        /// Lowercase heading fragment with source-order duplicate suffixes.
        pub slug: String,
    }

    /// Bounds on semantic tree construction and rich table adaptation.
    #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
    pub struct ParseLimits {
        /// Maximum parser events consumed during semantic construction.
        pub max_nodes: usize,
        /// Maximum nested parser containers and inline constructs.
        pub max_depth: usize,
        /// Maximum cells admitted to one rich table.
        pub max_table_cells: usize,
    }

    /// A UTF-8 byte offset in one identified reading unit.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub struct ReadingPosition {
        /// Identity of the associated reading unit.
        pub unit_id: u64,
        /// UTF-8 byte offset within the unit readable payload.
        pub offset: usize,
    }

    /// Two reading endpoints; either selection direction is valid.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub struct ReadingRange {
        /// The selection anchor endpoint.
        pub start: ReadingPosition,
        /// The selection head endpoint.
        pub end: ReadingPosition,
    }

    /// One source-addressed payload in document reading order.
    #[derive(Clone, Debug)]
    pub struct ReadingUnit {
        /// Opaque identity that is never recycled within its source epoch.
        pub id: u64,
        /// Original UTF-8 source range for this construct.
        pub source: Range<usize>,
        /// Semantic construct or payload category.
        pub kind: UnitKind,
        /// Readable text, excluding generated terminal decoration.
        pub text: String,
        /// Whether selection includes this entire payload.
        pub atomic: bool,
        /// Semantic spans whose offsets address this readable payload.
        pub spans: Vec<InlineSpan>,
        /// UTF-8 offsets of LF bytes that wrap as prose when displayed.
        pub soft_breaks: Vec<usize>,
    }

    /// A destination classified without filesystem inference or shell
    /// interpolation.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub enum ResolvedLink {
        /// A local heading fragment requiring no external host action.
        Fragment(String),
        /// A structured HTTP(S) URL eligible for an explicit host Open.
        External(Url),
        /// A document of the host's own, which only the host can find.
        Local(LocalLink),
        /// A destination that requires a base URL or explicit host handler.
        Unavailable(String),
    }

    /// One readable Markdown cell with source-derived column identity.
    #[derive(Clone, Debug)]
    pub struct TableCell {
        /// Stable source-derived key within the containing table.
        pub key: u64,
        /// Original cell bytes, absent for synthetic missing cells.
        pub source: Option<Range<usize>>,
        /// Readable text, excluding generated terminal decoration.
        pub text: String,
    }

    /// One body row with stable source-derived identity.
    #[derive(Clone, Debug)]
    pub struct TableRow {
        /// Stable source-derived key within the containing table.
        pub key: u64,
        /// Ordered cells, padded to the header column count.
        pub cells: Vec<TableCell>,
    }

    /// The readable payload represented by one reading unit.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub enum UnitKind {
        /// Readable prose, including literal provisional syntax.
        Prose,
        /// Parser-normalized code, selectable as one card.
        Code,
        /// A completed table with normalized cell values.
        Table,
        /// Exact source retained for inspection or literal presentation.
        Source,
        /// A logical separator with no decoration in copied text.
        Separator,
    }

    /// Recognize HTTP(S) URLs in ordinary text, balancing parentheses and trimming
    /// punctuation.
    pub fn bare_url_ranges(text: &str) -> Vec<Range<usize>>;

    /// Lowercase Unicode letters/digits, retain `_` and `-`, replace whitespace
    /// with `-`. Punctuation is omitted; repeated headings gain source-order `-1`,
    /// `-2` suffixes.
    pub fn heading_slug(text: &str) -> String;

    /// Parse one accepted revision. Limits degrade accepted content to recoverable
    /// source cards.
    pub fn parse_document(
        source: &SourceSnapshot,
        limits: &ParseLimits,
        previous: Option<&DocumentSnapshot>,
    ) -> DocumentSnapshot;

    /// The supported syntax is CommonMark with these explicit extensions.
    pub fn parser_options() -> Options;

    /// Resolve without filesystem inference. Only control-free HTTP(S) URLs can
    /// open by default. Without a base URL, a relative path or `file:` URL is
    /// local to the host.
    pub fn resolve_link(destination: &str, base: Option<&Url>) -> ResolvedLink;
}

pub mod executor {
    //! Bounded shared preparation and deterministic scheduling.
    //! Bounded Markdown work shared by the host's readers.
    //!
    //! Each reader owns a lane with one running request, one replaceable desired
    //! request, and one completed result. Owners acknowledge accepted and rejected
    //! results with the latest published base before the next preparation starts.

    /// Immutable payload retained until its FIFO copy request completes.
    #[derive(Clone, Debug)]
    pub enum CopyInput {
        /// Exact source bytes and a UTF-8 selection interval.
        Source {
            /// Shared exact bytes of the displayed revision.
            text: Arc<str>,
            /// Selected UTF-8 byte interval.
            range: Range<usize>,
        },
        /// A complete readable projection or a selected reading interval.
        Reading {
            /// Pinned immutable semantics used by this copy.
            document: Arc<DocumentSnapshot>,
            /// Optional readable selection; None copies every reading unit.
            selection: Option<ReadingRange>,
        },
        /// A link destination or one object's complete readable payload.
        Object {
            /// Pinned immutable semantics used by this copy.
            document: Arc<DocumentSnapshot>,
            /// Pinned object identity within the document.
            object_id: u64,
        },
        /// A small already-owned immutable payload, such as a host-provided URL.
        Text(Arc<str>),
    }

    /// One FIFO copy completion awaiting owner disposition.
    #[derive(Debug)]
    pub struct CopyResult {
        /// Host request identity captured before copy work was submitted.
        pub id: u64,
        /// Complete copied payload or an explicit failure; never partial output.
        pub result: Result<String, WorkError>,
    }

    /// Aggregate bounds for one host's Markdown work.
    #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
    pub struct ExecutorOptions {
        /// Maximum concurrent jobs; zero is normalized to one.
        pub worker_count: usize,
        /// Maximum registered reader lanes.
        pub max_documents: usize,
        /// Maximum accepted copies, including running and undisposed results.
        pub max_copy_jobs: usize,
        /// Aggregate retained input payload/header estimates and maximum output
        /// bytes of accepted copies, excluding allocator overhead.
        pub max_copy_bytes: usize,
    }

    /// A bounded snapshot of shared queue occupancy.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub struct ExecutorStats {
        /// Number of registered reader lanes.
        pub documents: usize,
        /// Jobs currently occupying workers.
        pub running: usize,
        /// Lanes retaining a latest desired preparation.
        pub desired: usize,
        /// Prepared results awaiting owner disposition.
        pub completed: usize,
        /// Reader lanes queued for fair worker selection.
        pub ready: usize,
        /// Maximum jobs that may run concurrently.
        pub worker_limit: usize,
        /// Whether admission and queued execution have stopped.
        pub stopped: bool,
        /// Accepted copies, including queued, running, and undisposed results.
        pub copy_jobs: usize,
        /// Reserved retained-input and maximum-output bytes for accepted copies.
        pub copy_bytes: usize,
    }

    /// A running job held by the controlled scheduler. Dropping it completes the
    /// handshake with cancellation, so a test cannot accidentally strand a lane.
    pub struct HeldWork {/* private fields */}

    impl HeldWork {
        /// Inspect the host request identity of a held copy job.
        pub fn copy_id(&self) -> Option<u64>;

        /// Deliver a controlled failure through the normal completion path.
        pub fn fail(self, message: impl Into<String>);

        /// Execute held work with panic containment and deliver its completion.
        pub fn finish(self);

        /// Inspect a held preparation request; copy jobs return None.
        pub fn request(&self) -> Option<&WorkRequest>;
    }

    impl Drop for HeldWork {}

    /// Deterministic driver for the same admission, queue, and completion
    /// machinery.
    #[derive(Clone, Debug)]
    pub struct ManualExecutor {/* private fields */}

    impl ManualExecutor {
        /// Reject one subsequent preparation admission for deterministic tests.
        pub fn reject_next_submission(&self);

        /// Run and deliver one job; return false when none can start.
        pub fn run_next(&self) -> bool;

        /// Deliver jobs until all remaining lanes await input or disposition.
        pub fn run_until_idle(&self);

        /// Start the next fair queued job while respecting the worker bound.
        pub fn start_next(&self) -> Option<HeldWork>;
    }

    /// Host-owned service. Clones share workers, queues, and all bounds.
    #[derive(Clone, Debug, Default)]
    pub struct MarkdownExecutor {/* private fields */}

    impl MarkdownExecutor {
        /// Waits for worker exit after explicit shutdown. Call from host teardown,
        /// never from removal of a Markdown node.
        pub fn join(&self);

        /// Creates the production queue with explicitly driven work completion.
        pub fn manual(options: ExecutorOptions) -> (Self, ManualExecutor);

        /// Start a host-owned worker pool, panicking if a thread cannot start.
        pub fn new(options: ExecutorOptions) -> Self;

        /// Reserve one reader lane, optionally attaching its runtime wake.
        pub fn register(&self, wake: Option<NodeWakeHandle>) -> Result<WorkHandle, SubmitError>;

        /// Stops admission and queued work; already running passes finish in the
        /// background. This method never joins a worker on the calling UI thread.
        pub fn shutdown(&self);

        /// Inspect aggregate occupancy without retaining any work payloads.
        pub fn stats(&self) -> ExecutorStats;

        /// Start a host-owned worker pool and report thread creation failures.
        pub fn try_new(options: ExecutorOptions) -> std::io::Result<Self>;
    }

    /// An owned representation ready for atomic UI publication.
    #[derive(Debug)]
    pub enum PreparedView {
        /// Semantic model and Rendered geometry published together.
        Rendered(Arc<PresentationSnapshot>),
        /// Exact accepted Source bytes with prepared editor layout.
        Source(Box<PreparedSource>),
    }

    /// A query result addressed in its prepared representation.
    #[derive(Debug)]
    pub enum SearchOutput {
        /// Exact raw-source byte ranges.
        Source(SourceMatches),
        /// Readable unit, line, or table-cell addresses.
        Rendered(SearchResults),
    }

    /// An admission failure; the owner retains responsibility for dirty work.
    #[derive(Clone, Copy, Debug, Display, Eq, Error, PartialEq)]
    pub enum SubmitError {
        /// The shared service no longer accepts work.
        Shutdown,
        /// A document, copy-count, or copy-byte bound was reached.
        Capacity,
        /// Admission was deliberately rejected by the controlled scheduler.
        Rejected,
    }

    /// A failed job that still completes the lane handshake.
    #[derive(Clone, Debug, Display, Eq, Error, PartialEq)]
    pub enum WorkError {
        /// The owner was removed, the executor stopped, or held work was dropped.
        Cancelled,
        /// An explicitly reported preparation or copy failure.
        Failed(String),
        /// A worker panic caught at the job boundary.
        WorkerPanicked(String),
    }

    /// One reader's bounded lane. Dropping it releases queued and completed data.
    #[derive(Debug)]
    pub struct WorkHandle {/* private fields */}

    impl WorkHandle {
        /// Releases the result handshake after publication or rejection. Any queued
        /// request builds on this actually published semantic base.
        pub fn acknowledge(&self, previous: Option<Arc<PresentationSnapshot>>);

        /// Rebase queued work on the last published semantics even when its cached
        /// Rendered geometry has been evicted. Every base belongs to this epoch.
        pub fn acknowledge_document(
            &self,
            previous: Option<Arc<PresentationSnapshot>>,
            source: Option<Arc<str>>,
            document: Option<Arc<DocumentSnapshot>>,
        );

        /// Rebase both prepared surfaces before releasing queued work. `source`
        /// must be the exact published Source bytes from the request's epoch.
        pub fn acknowledge_with_source(
            &self,
            previous: Option<Arc<PresentationSnapshot>>,
            source: Option<Arc<str>>,
        );

        /// Whether this lane retains work, results, or a publication handshake.
        pub fn is_pending(&self) -> bool;

        /// Attach or refresh the owner wake; signal any already completed result.
        pub fn set_wake(&self, wake: NodeWakeHandle);

        /// Replace the latest desired preparation without interrupting running
        /// work.
        pub fn submit(&self, request: WorkRequest) -> Result<(), SubmitError>;

        /// Admits an immutable copy without replacing earlier copy requests. The
        /// input and maximum output are reserved against aggregate byte bounds.
        pub fn submit_copy(
            &self,
            id: u64,
            input: CopyInput,
            max_bytes: usize,
        ) -> Result<(), SubmitError>;

        /// Takes a result for validation and publication. Call `acknowledge` after
        /// either accepting or rejecting it, supplying the latest published base.
        pub fn take_completed(&self) -> Option<WorkResult>;

        /// Take the oldest completed copy and release its capacity reservation.
        pub fn take_copy_completed(&self) -> Option<CopyResult>;
    }

    impl Drop for WorkHandle {}

    /// Immutable input. Reader interaction state is deliberately absent.
    #[derive(Clone, Debug)]
    pub struct WorkRequest {
        /// Exact accepted bytes and lifecycle to prepare.
        pub source: SourceSnapshot,
        /// Requested representation.
        pub view: ViewType,
        /// Allocated body geometry and layout preferences.
        pub geometry: GeometryKey,
        /// Source wrapping, numbering, and syntax preferences.
        pub source_options: SourceOptions,
        /// Previously published Rendered geometry available for layout reuse.
        pub previous: Option<Arc<PresentationSnapshot>>,
        /// Last published semantics, retained independently of cached geometry.
        pub previous_document: Option<Arc<DocumentSnapshot>>,
        /// Exact previously published Source bytes from the same epoch. Prefix
        /// verification happens on the worker before UI publication.
        pub previous_source: Option<Arc<str>>,
        /// Semantic construction bounds.
        pub limits: ParseLimits,
        /// Owner generation for view and geometry changes.
        pub generation: u64,
        /// Optional query over this request's exact projection.
        pub search: Option<WorkSearch>,
        /// What the reader knows of the document's images.
        pub images: Arc<ImageSizes>,
    }

    impl WorkRequest {
        /// Capture the complete immutable identity of this request.
        pub fn tags(&self) -> WorkTags;
    }

    /// One completed preparation, including its exact request provenance.
    #[derive(Debug)]
    pub struct WorkResult {
        /// The request snapshot, retained for exact publication provenance.
        pub source: SourceSnapshot,
        /// Identity checked by the owner before publication.
        pub tags: WorkTags,
        /// Prepared owned data or a recoverable worker failure.
        pub result: Result<PreparedView, WorkError>,
        /// Optional bounded query results, independently reporting query errors.
        pub search: Option<Result<SearchOutput, String>>,
    }

    /// A query over the exact snapshot carried by its preparation request.
    #[derive(Clone, Debug)]
    pub struct WorkSearch {
        /// Retained query text and explicit matching behavior.
        pub query: SearchQuery,
        /// Owner query generation used to reject obsolete results.
        pub generation: u64,
        /// Bounds on query compilation, scan bytes, and stored matches.
        pub limits: SearchLimits,
    }

    /// Identity checked by the owner immediately before publishing a result.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub struct WorkTags {
        /// Source identity, changed on replacement.
        pub epoch: u64,
        /// Accepted source revision, including lifecycle changes.
        pub revision: u64,
        /// Prepared representation.
        pub view: ViewType,
        /// Geometry used by this preparation.
        pub geometry: GeometryKey,
        /// Source preferences used by this preparation.
        pub source_options: SourceOptions,
        /// Semantic limits used by this preparation.
        pub limits: ParseLimits,
        /// Owner generation captured at submission.
        pub generation: u64,
        /// Optional query generation captured at submission.
        pub query_generation: Option<u64>,
    }
}

pub mod host {
    //! Host requests and replies.
    //! Immutable, explicitly activated host actions and bounded reply tracking.

    /// An effect the embedding application may perform once.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub enum HostAction {
        /// Copy this complete payload to the host clipboard.
        CopyText(String),
        /// Open this validated, resolved URL through the host browser service.
        OpenUrl(String),
        /// Follow a link to a document of the host's own, which the host finds.
        OpenLocal(LocalLink),
    }

    /// The result of one host request.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub enum HostOutcome {
        /// The host performed the action.
        Success,
        /// Host policy declined the action.
        Rejected(String),
        /// The host attempted the action but it failed.
        Failed(String),
    }

    /// A reply to a request that the host has already drained.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub struct HostReply {
        /// Request being acknowledged.
        pub id: u64,
        /// Success, rejection, or failure.
        pub outcome: HostOutcome,
    }

    /// A unique host action, frozen at the displayed revision of its activation.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub struct HostRequest {
        /// Monotonic identifier, not reused on document replacement.
        pub id: u64,
        /// The document epoch at activation.
        pub epoch: u64,
        /// The displayed source revision at activation.
        pub revision: u64,
        /// Selected object identity, if this came from an object.
        pub object: Option<u64>,
        /// One complete immutable effect.
        pub action: HostAction,
    }

    /// The host's answer to a resource request.
    #[derive(Clone, Debug)]
    pub enum Resource {
        /// The image, which the host bounds in size.
        Image(Arc<RgbaImage>),
        /// Nothing the request names exists.
        Missing,
        /// The host could not supply it, and why.
        Failed(String),
    }

    /// What a resource request asks the host for.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum ResourceKind {
        /// An image an image block shows.
        Image,
    }

    /// A resource the document needs from the host. Unlike a [`HostAction`], a
    /// reader may need a resource again, so resources travel on their own
    /// requests.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub struct ResourceRequest {
        /// Identifier the reply names; never reused.
        pub id: u64,
        /// The document epoch that needs it.
        pub epoch: u64,
        /// The document of the host's own that holds it.
        pub target: LocalLink,
        /// What the reader asks for.
        pub kind: ResourceKind,
    }
}

pub mod options {
    //! Reader configuration and state values.
    //! Host choices and independent reader state values.

    pub use crate::{Follow, MarkdownOptions, Mode as MarkdownMode, Mode, ViewType};
}

pub mod presentation {
    //! Prepared terminal presentation.
    //! Immutable Markdown geometry. Preparation owns wrapping; painting visits only
    //! visible rows.

    /// All preferences that influence line layout. Width includes the reserved
    /// gutter.
    #[derive(Clone, Copy, Debug, Default, Eq, Hash, PartialEq)]
    pub struct GeometryKey {
        /// Available canvas width, including the reserved scrollbar gutter.
        pub width: u32,
        /// Decoration preset used during preparation.
        pub glyphs: GlyphPreset,
        /// Blank rows between blocks, capped at three.
        pub spacing: u8,
        /// Preferred maximum prose width; cards use the body width.
        pub prose_width: u32,
        /// Cumulative eligible code-payload bytes admitted for automatic syntax.
        pub syntax_limit: usize,
        /// Block mosaics that the terminal draws, which big headings draw with.
        pub mosaic: Tier,
    }

    /// Decorations are geometry, so changing this preset requires preparation.
    #[derive(Clone, Copy, Debug, Default, Eq, Hash, PartialEq)]
    pub enum GlyphPreset {
        /// Unicode rails, bullets, rules, and clipping marks.
        #[default]
        Unicode,
        /// Portable ASCII decoration.
        Ascii,
    }

    /// Semantic address under a prepared document cell.
    #[derive(Clone, Debug)]
    pub struct Hit {
        /// Reading position at the whole grapheme under the pointer.
        pub reading: Option<ReadingPosition>,
        /// Actionable object under the pointer.
        pub object: Option<u64>,
        /// Owning source span; this is not an invented character map.
        pub source: Range<usize>,
    }

    /// What the reader knows of an image, by its destination.
    #[derive(Clone, Debug, Eq, Hash, PartialEq)]
    pub enum ImageInfo {
        /// The supplied image's size in pixels.
        Size {
            /// Width in pixels.
            width: u32,
            /// Height in pixels.
            height: u32,
        },
        /// The host could not supply it, and why.
        Failed(String),
    }

    /// Supplied images by destination, and the mosaic grids drawn from them.
    #[derive(Clone, Debug, Default)]
    pub struct ImagePixels {
        /// Supplied images, by destination.
        pub images: HashMap<String, Arc<RgbaImage>>,
        /* private fields */
    }

    impl !Send for ImagePixels {}
    impl !Sync for ImagePixels {}

    /// What the reader knows of each image, by its destination.
    pub type ImageSizes = HashMap<String, ImageInfo>;

    /// Reader-owned decoration applied without invalidating geometry.
    #[derive(Clone, Debug, Default)]
    pub struct PaintOverlays {
        /// Current document selection in readable UTF-8 coordinates.
        pub selection: Option<ReadingRange>,
        /// Retained matches in the rendered readable projection.
        pub search: Vec<ReadingRange>,
        /// Current object cursor, independent of document selection.
        pub active_object: Option<u64>,
        /// Images the host supplied, which image blocks paint.
        pub images: ImagePixels,
    }

    impl !Send for PaintOverlays {}
    impl !Sync for PaintOverlays {}

    /// Paint work is bounded by the supplied visible rectangle, never document
    /// length.
    #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
    pub struct PaintStats {
        /// Visible document rows visited.
        pub rows: usize,
        /// Prepared runs visited within those rows.
        pub runs: usize,
        /// Visible graphemes considered for painting.
        pub graphemes: usize,
        /// Shared table previews painted.
        pub tables: usize,
    }

    /// Preparation evidence, independent of paint work.
    #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
    pub struct PreparationStats {
        /// Blocks newly laid out by this preparation.
        pub prepared_blocks: usize,
        /// Blocks whose immutable layout was reused unchanged.
        pub reused_blocks: usize,
        /// Total indexed document rows.
        pub rows: usize,
        /// Code-payload bytes reserved within the document's syntax budget.
        pub syntax_bytes: usize,
    }

    /// One document row. Decoration has no reading range and never enters copy.
    #[derive(Clone, Debug)]
    pub struct PreparedRow {
        /// Positioned display runs in increasing cell order.
        pub runs: Vec<PreparedRun>,
        /// Reading unit owning this row, including its decoration.
        pub unit_id: u64,
        /// Original source span of the owning block.
        pub source: Range<usize>,
        /// Ground palette role, painted across empty line ends.
        pub ground: &'static str,
        /// First cell the ground covers. Cells before it take the text ground,
        /// so quote rails stay outside a card.
        pub ground_x: u32,
        /// Whether document selection treats the unit as one whole payload.
        pub atomic: bool,
    }

    /// A run is already sanitized and fitted to its row. Ranges address readable
    /// UTF-8 bytes.
    #[derive(Clone, Debug)]
    pub struct PreparedRun {
        /// Starting terminal cell within the document canvas.
        pub x: u32,
        /// Display cells occupied by the sanitized text.
        pub width: u32,
        /// Terminal-safe display text, already fitted to its row.
        pub text: String,
        /// Palette role resolved during painting.
        pub role: &'static str,
        /// Readable UTF-8 byte range; absent for generated decoration.
        pub reading: Option<Range<usize>>,
        /// Actionable object covering this run, if any.
        pub object: Option<u64>,
        /* private fields */
    }

    /// Interpretation, geometry, and hit maps publish as one immutable value.
    #[derive(Debug)]
    pub struct PresentationSnapshot {
        /// Semantic interpretation retained with this geometry.
        pub document: Arc<DocumentSnapshot>,
        /// Preferences used to build every row and hit map.
        pub geometry: GeometryKey,
        /// Work performed while preparing this snapshot.
        pub stats: PreparationStats,
        /// The prepared-row bound omitted trailing display content.
        pub truncated: bool,
        /* private fields */
    }

    impl PresentationSnapshot {
        /// Conservative owned layout-cache bytes, excluding the semantic model and
        /// accepted source. Shared row and table allocations count once within this
        /// snapshot; counting two cached snapshots separately can overestimate
        /// them. This constant-time observation never scans source or prepared
        /// rows.
        pub fn derived_bytes(&self) -> usize;

        /// Indexed canvas height, including block decoration and spacing.
        pub fn height(&self) -> u32;

        /// Map a canvas cell to a whole readable grapheme or atomic card.
        pub fn hit(&self, point: Point) -> Option<Hit>;

        /// Paint the visible document rectangle at viewport origin zero. This
        /// method never parses, wraps, or highlights source.
        pub fn paint(
            &self,
            render: &mut Render<'_>,
            visible: Rect,
            overlays: &PaintOverlays,
        ) -> canopy::error::Result<PaintStats>;

        /// Run this on the document worker. A palette change does not invalidate
        /// it.
        pub fn prepare(
            document: Arc<DocumentSnapshot>,
            geometry: GeometryKey,
            previous: Option<&Self>,
        ) -> Self;

        /// Prepare as [`Self::prepare`] does, with what the reader knows of the
        /// document's images, so an image block reserves its image's rows.
        pub fn prepare_with(
            document: Arc<DocumentSnapshot>,
            geometry: GeometryKey,
            previous: Option<&Self>,
            images: &ImageSizes,
        ) -> Self;

        /// Share the identical dataset and geometry with the table inspector.
        pub fn prepared_table(&self, unit_id: u64) -> Option<Arc<PreparedTable>>;

        /// Resolve one row through the block-height index.
        pub fn row(&self, index: u32) -> Option<&PreparedRow>;

        /// Find the source-containing block and its nearest mapped readable row.
        pub fn row_for_source(&self, source: usize) -> u32;

        /// Restore a readable byte position after geometry changes.
        pub fn row_for_unit(&self, unit_id: u64, offset: usize) -> u32;

        /// Map a reading position to verified source bytes, falling back to its
        /// block's start.
        pub fn source_at_reading(&self, position: ReadingPosition) -> Option<usize>;

        /// Map a row to verified source bytes, falling back to the block start.
        pub fn source_at_row(&self, row: u32) -> Option<usize>;

        /// Canvas width from the geometry key.
        pub fn width(&self) -> u32;
    }

    /// Install palette roles once; all colors are resolved during painting.
    pub fn register_styles(map: &mut StyleMap, palette: &Palette);

    /// Pass directly to `Setup::widget_styles` to retain roles through theme
    /// changes.
    pub fn style_rules(palette: &Palette, rules: StyleRules<'_>);
}

pub mod search {
    //! Bounded literal and regex queries.
    //! Bounded, line-local matching shared by source and readable projections.

    /// A compiled line-local matcher reusable across source revisions.
    pub struct CompiledQuery {/* private fields */}

    impl CompiledQuery {
        /// Compile one bounded query; reject multiline text and invalid regex.
        pub fn new(query: &SearchQuery, limits: &SearchLimits) -> Result<Self, SearchError>;
    }

    /// The readable location containing one search match.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub enum SearchAddress {
        /// A prose reading unit.
        Unit {
            /// Identity of the associated reading unit.
            unit_id: u64,
        },
        /// A line within an atomic code card.
        CodeLine {
            /// Identity of the associated reading unit.
            unit_id: u64,
            /// Zero-based line index within the addressed payload.
            line: usize,
        },
        /// A line within a source card.
        SourceCardLine {
            /// Identity of the associated reading unit.
            unit_id: u64,
            /// Zero-based line index within the addressed payload.
            line: usize,
        },
        /// One table cell, independently searchable.
        TableCell {
            /// Identity of the associated reading unit.
            unit_id: u64,
            /// Body row identity, or None for the header.
            row_key: Option<u64>,
            /// The source-derived column identity.
            column_key: u64,
        },
    }

    /// Case sensitivity shared by Source and Rendered search.
    #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
    pub enum SearchCase {
        /// Match case exactly.
        #[default]
        Sensitive,
        /// Ignore letter case.
        Insensitive,
        /// Match case only when the expression contains literal uppercase letters.
        Smart,
    }

    /// A query validation, compilation, or matching diagnostic.
    #[derive(Clone, Debug, Display, Eq, Error, PartialEq)]
    pub struct SearchError(pub String);

    /// Bounds on query compilation, scanned bytes, and result storage.
    #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
    pub struct SearchLimits {
        /// Maximum UTF-8 query size before compilation.
        pub max_query_bytes: usize,
        /// Maximum stored match records; covered matches are still counted.
        pub max_matches: usize,
        /// Maximum source or readable bytes examined in this run.
        pub max_scan_bytes: usize,
    }

    /// A nonempty match with both UTF-8 byte and character offsets.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub struct SearchMatch {
        /// Exact accepted-source bytes when the projection preserves raw source.
        pub source_range: Option<Range<usize>>,
        /// The unit, line, or cell containing the match.
        pub address: SearchAddress,
        /// UTF-8 byte range in the addressed readable text.
        pub range: Range<usize>,
        /// Zero-based character columns within the matched line.
        pub char_range: Range<usize>,
    }

    /// How a query interprets its text.
    #[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
    pub enum SearchMode {
        /// Match the query as literal text.
        #[default]
        Literal,
        /// Use the same ripgrep regular-expression syntax as fh.
        Regex,
    }

    /// A retained query with explicit matching semantics.
    #[derive(Clone, Debug, Default, Eq, PartialEq)]
    pub struct SearchQuery {
        /// Readable text, excluding generated terminal decoration.
        pub text: String,
        /// Literal or regular-expression matching.
        pub mode: SearchMode,
        /// Explicit case-sensitivity policy.
        pub case: SearchCase,
    }

    /// Revision-addressed results with explicit coverage and storage bounds.
    #[derive(Clone, Debug)]
    pub struct SearchResults {
        /// Source identity; replacement allocates a new epoch.
        pub epoch: u64,
        /// Monotonic accepted revision within this source epoch.
        pub revision: u64,
        /// The query generation that produced these results.
        pub generation: u64,
        /// Stored matches in reading order.
        pub matches: Vec<SearchMatch>,
        /// Total matches in the covered window, including hits beyond storage
        /// capacity.
        pub count: usize,
        /// Whether all searchable bytes were examined.
        pub coverage_complete: bool,
        /// Whether matching records exceeded the storage bound.
        pub storage_limited: bool,
        /// Bytes consumed from the configured search window.
        pub scanned_bytes: usize,
    }

    /// Search readable units, code lines, and table cells independently.
    pub fn search_document(
        document: &DocumentSnapshot,
        query: &CompiledQuery,
        generation: u64,
        limits: &SearchLimits,
    ) -> SearchResults;
}

pub mod source_store {
    //! Accepted source and streaming lifecycle.
    //! Exact, append-only accepted source. Snapshots keep accepted revisions
    //! immutable.

    pub use crate::{DocumentInput, FinishOutcome};

    /// Default maximum accepted source size, in bytes.
    pub const DEFAULT_SOURCE_LIMIT: usize = _;

    /// Whether a producer can append to the current source epoch.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub enum Lifecycle {
        /// A source epoch that still accepts appends.
        Receiving,
        /// A complete static document or closed source epoch.
        Complete(FinishOutcome),
    }

    impl Lifecycle {
        /// Return whether appending is closed for this epoch.
        pub fn is_complete(&self) -> bool;
    }

    /// An append or replacement rejected without accepted-state mutation.
    #[derive(Clone, Debug, Display, Eq, Error, PartialEq)]
    pub enum SourceError {
        /// A complete static document or closed source epoch.
        Complete,
        /// The operation would exceed the accepted source byte limit.
        Limit {
            /// Configured maximum accepted source bytes.
            limit: usize,
            /// Total source bytes the rejected operation would have retained.
            attempted: usize,
        },
    }

    /// An immutable accepted revision with shared append chunks.
    #[derive(Clone, Debug)]
    pub struct SourceSnapshot {
        /// Source identity; replacement allocates a new epoch.
        pub epoch: u64,
        /// Monotonic accepted revision within this source epoch.
        pub revision: u64,
        /// The producer lifecycle attached to this exact revision.
        pub lifecycle: Lifecycle,
        /* private fields */
    }

    impl SourceSnapshot {
        /// Return the number of nonempty accepted append chunks.
        pub fn chunk_count(&self) -> usize;

        /// Bytes in a separately allocated contiguous source cache, without
        /// creating that cache. Single-chunk text shares its accepted allocation.
        pub fn flattened_bytes(&self) -> usize;

        /// Return whether no bytes have been accepted.
        pub fn is_empty(&self) -> bool;

        /// Return the exact accepted byte count.
        pub fn len(&self) -> usize;

        /// Copy an exact source range, rejecting invalid UTF-8 boundaries.
        pub fn slice(&self, range: Range<usize>) -> Option<String>;

        /// Flatten once and share the exact accepted UTF-8 bytes.
        pub fn text(&self) -> Arc<str>;
    }

    /// The unique append authority for a source epoch.
    #[derive(Debug, Default)]
    pub struct SourceStore {/* private fields */}

    impl SourceStore {
        /// Accept all nonempty UTF-8 input or leave accepted state unchanged.
        pub fn append(&mut self, text: &str) -> Result<bool, crate::source_store::SourceError>;

        /// Complete the epoch once, advancing revision without adding bytes.
        pub fn finish(&mut self, outcome: FinishOutcome) -> bool;

        /// Start a new epoch atomically, preserving the old one on rejection.
        pub fn replace(
            &mut self,
            text: &str,
            receiving: bool,
        ) -> Result<(), crate::source_store::SourceError>;

        /// Capture the current immutable accepted revision.
        pub fn snapshot(&self) -> SourceSnapshot;

        /// Adopt complete source with the default byte limit.
        pub fn static_text(
            text: impl Into<Arc<str>>,
        ) -> Result<Self, crate::source_store::SourceError>;

        /// Adopt complete source without copying an existing Arc payload.
        pub fn static_with_limit(
            text: impl Into<Arc<str>>,
            limit: usize,
        ) -> Result<Self, crate::source_store::SourceError>;

        /// Start an empty receiving epoch with the default source limit.
        pub fn stream() -> Self;

        /// Start an empty receiving epoch with an explicit byte limit.
        pub fn with_limit(limit: usize) -> Self;
    }
}

pub mod source_view {
    //! Exact source text viewing.
    //! Read-only Markdown source presentation over immutable accepted UTF-8 bytes.

    pub use crate::MarkdownSource;

    /// Owned source geometry and highlighting prepared without UI access.
    ///
    /// Preparation scans the source, builds the byte map, wraps every line, and
    /// optionally highlights within the syntax cap. Publishing and painting do
    /// not repeat this work. Reprepare at a changed width before publishing it.
    #[derive(Debug)]
    pub struct PreparedSource {/* private fields */}

    impl PreparedSource {
        /// Retained derived storage estimate, computed on the preparing worker.
        /// Accepted source bytes and shared executor allocations are excluded.
        pub fn derived_bytes(&self) -> usize;

        /// Prepare one immutable source revision at its allocated body width.
        pub fn new(
            epoch: u64,
            revision: u64,
            source: Arc<str>,
            width: u32,
            options: SourceOptions,
        ) -> Self;

        /// Verify an append against the currently displayed immutable source.
        ///
        /// Run this on the preparation worker. Publication recognizes the shared
        /// prefix identity and does not rescan accepted bytes on the UI thread.
        pub fn verify_prefix(
            self,
            previous: Arc<str>,
        ) -> Result<Self, crate::source_view::SourceError>;
    }

    /// A source location within one document epoch.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub struct SourceAnchor {
        /// Document epoch.
        pub epoch: u64,
        /// UTF-8 byte position in the accepted source.
        pub byte: usize,
    }

    /// Source publication, range, or bounded-output failure.
    #[derive(Clone, Debug, Display, Eq, Error, PartialEq)]
    pub enum SourceError {
        /// Same-epoch publication would change an already accepted prefix.
        NonAppend,
        /// A publication is older than the displayed revision.
        Stale,
        /// An unfinished drag pins the current geometry.
        DragActive,
        /// An anchor belongs to another document.
        WrongEpoch,
        /// A range is outside the source or cuts a UTF-8 character.
        InvalidRange,
        /// Exact output would exceed its configured byte budget.
        OutputLimit,
        /// The query exceeds its configured byte budget.
        QueryLimit,
        /// A regular expression failed to compile or match.
        Regex(String),
    }

    /// A bounded match window over a specific immutable revision.
    #[derive(Clone, Debug)]
    pub struct SourceMatches {
        /// Document epoch.
        pub epoch: u64,
        /// Displayed source revision.
        pub revision: u64,
        /// Exact source byte ranges, in ascending order.
        pub ranges: Vec<Range<usize>>,
        /// Whether the full source was scanned without exhausting result storage.
        pub complete: bool,
    }

    /// Geometry and automatic syntax-work bounds for a source presentation.
    #[derive(Clone, Debug, Default, Eq, PartialEq)]
    pub struct SourceOptions {
        /// Soft wrapping or horizontal scrolling.
        pub wrap: WrapMode,
        /// Optional line-number gutter.
        pub line_numbers: LineNumbers,
        /// Tab stops, in terminal cells.
        pub tab_stop: usize,
        /// Maximum source and terminal-safe display bytes to highlight
        /// automatically.
        pub syntax_limit: usize,
        /// Fence language information, or `None` for plain text. Accepts grammar
        /// names, extensions, aliases, and comma suffixes such as `rust,ignore`.
        /// Markdown uses `md`; unknown languages remain plain text.
        pub language: Option<Arc<str>>,
    }
}
